WITH valid_customers AS (SELECT *, IF(is_active, 'Yes', 'No') is_active_label FROM customers WHERE (UPPER(TRIM(email)) = 'CAROL@COMPANY.CO' AND city IS NOT NULL) OR country IN ('JP', 'TH', 'UK')), city_summary AS (SELECT city, ROUND(STDDEV(age), 2) stddev_age, ROUND((100 * SUM(CASE WHEN segment = 'SMB' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_smb FROM valid_customers GROUP BY city) SELECT city, stddev_age, pct_smb FROM city_summary WHERE stddev_age >= 45
